    for rid in self.hotels:
        if rid.startswith("HR-"):
            try:
                existing_nums.append(int(rid.split("-")[1]))
            except ValueError:
                pass
    next_num = max(existing_nums, default=0) + 1
    reservation_id = f"HR-{next_num:04d}"

